<?php require APP_ROOT.'/services/chat.php';$u=require_role($customerPage?['KHACH_HANG']:['NHAN_VIEN','ADMIN']);$base=($customerPage?'khach_hang':'nhan_vien').'/tu_van.php';$id=(int)get('id');
handle_form(function()use($u,$base){switch(post('action')){case'create':$id=create_chat($u,post('cau_hinh'),post('noi_dung'));redirect($base.'?id='.$id);case'claim':claim_chat($u,(int)post('id'));break;case'online':must($u['quyen']==='NHAN_VIEN','Chỉ nhân viên mở ca trực.');execute('INSERT INTO nhan_vien_truc(nhan_vien_id,online_luc)VALUES(?,NOW()) ON DUPLICATE KEY UPDATE online_luc=NOW()',[$u['id']]);$_SESSION['chat_online']=true;break;case'end':$h=conversation((int)post('id'),$u);must($u['quyen']!=='KHACH_HANG','Nhân viên kết thúc phiên tư vấn.');execute("UPDATE hoi_thoai_chat SET trang_thai='DA_KET_THUC',ket_qua=? WHERE ma_hoi_thoai=?",[valid_text(post('ket_qua'),2000,false),$h['ma_hoi_thoai']]);break;}},$base.($id?'?id='.$id:''));
page_start('Tư vấn trực tuyến','Trao đổi với showroom, nhận hình ảnh và báo giá của phiên bản bạn quan tâm.');
if($customerPage){echo '<details '.(get('cau_hinh')?'open':'').'><summary>Gửi yêu cầu tư vấn mới</summary>';token_form();field('action','','create','hidden');select_field('cau_hinh','Phiên bản quan tâm',choices('SELECT ma_cau_hinh,ten_cau_hinh FROM cau_hinh_xe WHERE hien_thi=1','ma_cau_hinh','ten_cau_hinh'),get('cau_hinh'));textarea('noi_dung','Nhu cầu / câu hỏi');if((int)date('G')<(int)setting('chat_open_hour')||(int)date('G')>=(int)setting('chat_close_hour'))notice('Hiện ngoài giờ trực. Vui lòng ghi xe quan tâm và nhu cầu; nhân viên sẽ liên hệ theo hồ sơ của bạn.');echo '<button>Gửi yêu cầu</button></form></details>';}
elseif($u['quyen']==='NHAN_VIEN'){token_form();echo '<button name="action" value="online">Bắt đầu / tiếp tục ca trực</button></form>';if(!empty($_SESSION['chat_online']))echo '<div data-presence="'.e(url('api/nhan_vien_truc.php')).'" data-csrf="'.e(csrf_token()).'"></div>';}
$where=$customerPage?'h.khach_hang_id='.(int)$u['id']:($u['quyen']==='ADMIN'?'1=1':'(h.nhan_vien_id='.(int)$u['id'].' OR h.nhan_vien_id IS NULL)');table_start(['Hội thoại','Khách','Xe quan tâm','Trạng thái','']);foreach(db_all("SELECT h.*,t.ho_ten FROM hoi_thoai_chat h JOIN tai_khoan t ON t.id=h.khach_hang_id WHERE $where ORDER BY h.ma_hoi_thoai DESC LIMIT 100")as$r){echo '<tr><td>#'.(int)$r['ma_hoi_thoai'].'</td><td>'.e($r['ho_ten']).'</td><td>'.e($r['ma_cau_hinh']).'</td><td>'.badge($r['trang_thai']).'</td><td>';if(chat_access($u,$r))echo '<a href="'.e(url($base.'?id='.$r['ma_hoi_thoai'])).'">Mở</a>';elseif($u['quyen']==='NHAN_VIEN'&&$r['nhan_vien_id']===null){token_form();field('id','',$r['ma_hoi_thoai'],'hidden');echo '<button class="small" name="action" value="claim">Nhận tư vấn</button></form>';}echo '</td></tr>';}table_end();
if($id){$h=conversation($id,$u);echo '<div class="panel"><h2>Hội thoại #'.$id.'</h2><div class="chat-log" data-chat="'.e(url('api/tin_nhan.php?id='.$id)).'" data-user="'.(int)$u['id'].'"></div>';if($h['trang_thai']!=='DA_KET_THUC'){echo '<form id="chat-form" action="'.e(url('api/gui_tin.php')).'" method="post" enctype="multipart/form-data">'.csrf_field();field('id','',$id,'hidden');textarea('noi_dung','Tin nhắn');field('file','Ảnh hoặc PDF (tối đa 5 MB)','','file','accept="image/jpeg,image/png,image/webp,application/pdf"');echo '<button>Gửi tin nhắn</button><p id="chat-error" class="muted"></p></form>';}
foreach(db_all('SELECT * FROM bao_gia WHERE ma_hoi_thoai=? ORDER BY id DESC',[$id])as$q)echo '<p>Báo giá #'.(int)$q['id'].' · '.e(money($q['gia_chot'])).' · Hiệu lực đến '.e($q['hieu_luc_den']).'<br>'.e($q['dieu_kien']).'</p>';
if(!$customerPage&&$h['trang_thai']!=='DA_KET_THUC'){echo '<a class="button ghost" href="'.e(url('nhan_vien/bao_gia.php?id='.$id)).'">Lập báo giá</a>';token_form();field('id','',$id,'hidden');textarea('ket_qua','Kết quả tư vấn');echo '<button name="action" value="end" class="ghost">Kết thúc hội thoại</button></form>';}echo '</div>';}
page_end();
